import java.util.*;
import java.io.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][][] dp;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        n = Integer.parseInt(inputLine[0]);
        mod = Integer.parseInt(inputLine[1]);

        // Initialize dp array: 2 x (n+1) x (max_inv*2+1)
        int maxInv = n * (n - 1) / 2;
        int offset = maxInv + 1; // To handle negative indices
        dp = new Map[n + 1][2][];
        for (int i = 0; i <= n; i++) {
            for (int flag = 0; flag < 2; flag++) {
                dp[i][flag] = new Map[2 * maxInv + 1];
                for (int kIdx = 0; kIdx < 2 * maxInv + 1; kIdx++) {
                    dp[i][flag][kIdx] = new HashMap<>();
                }
            }
        }

        int answer = solve(n, 0, 1, offset, maxInv);
        System.out.println(answer % mod);
    }

    static int solve(int N, int K, int flag, int offset, int maxInv) {
        int kIdx = K + offset;
        if (dp[N][flag][kIdx].containsKey(K)) {
            return dp[N][flag][kIdx].get(K);
        }
        if (N == 1) {
            int res = (flag == 0) ? 0 : (K < 0 ? 1 : 0);
            dp[N][flag][kIdx].put(K, res);
            return res;
        }
        int max_inv = maxInv;
        if (K < -max_inv - 1) {
            int res = solve(N, -max_inv - 1, flag, offset, maxInv);
            dp[N][flag][kIdx].put(K, res);
            return res;
        }
        if (K >= max_inv) {
            dp[N][flag][kIdx].put(K, 0);
            return 0;
        }
        long total = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag == 1 && delta > 0) continue;
            int weight = Math.min(N - delta, delta + N);
            int newFlag = flag & (delta == 0 ? 1 : 0);
            total += (long) solve(N - 1, K - delta, newFlag, offset, maxInv) * weight;
            total %= mod;
        }
        dp[N][flag][kIdx].put(K, (int) total);
        return (int) total;
    }
}
